  "hints": [],
  "lesson": "# Pairwise distances\n\n`X` is (n, d) and `Y` is (m, d); return the (n, m) matrix of Euclidean distances, with no Python-level loop.\n\n**Interview signal:** broadcasting `(n,1,d) - (1,m,d)` is correct but allocates n*m*d. The expansion `|x|² + |y|² - 2x·y` uses one matmul, but rounding can make a squared distance slightly *negative* (identical points), and `sqrt` of that is NaN. Clip at zero.\n",
  "spec": "\"\"\"Starter file shown to the player.\"\"\"\nimport numpy as np\n\n\ndef pairwise_dists(X, Y):\n    \"\"\"Return D with D[i, j] = Euclidean distance between row X[i] and row Y[j]. No Python loops.\"\"\"\n    raise NotImplementedError\n",
  "visibleTests": "import numpy as np\nfrom nc_test import assert_close, python_lines\n\n\ndef test_small_example():\n    X = np.array([[0.0, 0.0], [3.0, 4.0]])\n    Y = np.array([[0.0, 0.0], [6.0, 8.0], [3.0, 0.0]])\n    assert_close(pairwise_dists(X, Y), [[0, 10, 3], [5, 5, 4]])\n\n\ndef test_shape():\n    rng = np.random.default_rng(0)\n    assert pairwise_dists(rng.normal(size=(4, 3)), rng.normal(size=(6, 3))).shape == (4, 6)\n\ndef _vectorised(fn, *args, limit=40):\n    out, lines = python_lines(fn, *args)\n    assert lines <= limit, f\"{lines} Python lines executed: the work is happening in a Python loop, not in numpy\"\n    return out\n",
  "hiddenTests": "import numpy as np\nfrom nc_test import assert_close, python_lines\n\n\ndef _brute(X, Y):\n    return np.array([[np.sqrt(((a - b) ** 2).sum()) for b in Y] for a in X])\n\n\ndef test_hidden_matches_brute_force_on_random_data():\n    for seed in range(5):\n        rng = np.random.default_rng(seed)\n        X, Y = rng.normal(size=(7, 4)), rng.normal(size=(5, 4))\n        assert_close(pairwise_dists(X, Y), _brute(X, Y), atol=1e-7)\n\n\ndef test_hidden_identical_points_give_zero_not_nan():\n    rng = np.random.default_rng(1)\n    X = rng.normal(size=(50, 16)) * 10 + 1e3\n    D = pairwise_dists(X, X)\n    assert not np.isnan(D).any(), \"rounding made a squared distance negative; clip before sqrt\"\n    assert np.all(np.diag(D) < 1e-3)\n\n\ndef test_hidden_single_row_and_dimension_one():\n    assert_close(pairwise_dists([[2.0]], [[5.0], [-1.0]]), [[3, 3]])\n\n\ndef test_hidden_no_python_loop_over_rows():\n    rng = np.random.default_rng(2)\n    X, Y = rng.normal(size=(300, 8)), rng.normal(size=(200, 8))\n    D = _vectorised(pairwise_dists, X, Y)\n    assert D.shape == (300, 200)\n\ndef _vectorised(fn, *args, limit=40):\n    out, lines = python_lines(fn, *args)\n    assert lines <= limit, f\"{lines} Python lines executed: the work is happening in a Python loop, not in numpy\"\n    return out\n"
